var ht = new HT({
        token: "5e5b1a0b1d7be497fb1c40b58ab7cf74"
    });

$("#pop-up_newsapioschat").on( "click keypress", function(e) {
				      openChat('https://live.sapios.com.br/webchat/?t=b5bd7dd8-e51c-4f38-82f0-b3f272187b13&openit=true&chatbubble=false');


                window.onmessage = function (e) {
                    if (e.data == 'closedSapiosChat') {
                        $('#sapioschat-container, #sapioschat-widget').removeClass('acsb-sr-only');
                        //dont remove this
                        setContainerHeight("85px")
                        $('#sapioschat-container').hide()
                        $('#pop-up_newsapioschat').show()

                    } else if (e.data == 'openedSapiosChat') {
                        $('#sapioschat-container, #sapioschat-widget').removeClass('acsb-sr-only');
                        //dont remove this
                        setContainerHeight("100%")
                        $('#sapioschat-container').show()
                        $('#pop-up_newsapioschat').hide()
                    }
            };  
          setContainerHeight("85px") 

    });;

