$(document).ready(function () {
  $('#tabButtons ul li').click(function (e) {
    e.preventDefault();
    $('#tabButtons ul li').removeClass('active'); //remove de todos os botões
    $(this).addClass('active'); //adiciona a classe no botão clicado

    const tabName = $(this).attr('data-tab');

    $('#tabContent .tab').removeClass('active'); //remove de todas as tabs
    $('#tabContent #' + tabName).addClass('active'); //adiciona na classe clicada
  });
});;

